mapper.select:
select stock_id, item_type, item_id, product_id, shop_dept_id,
       warehouse_id, available_quantity, version
from inv_stock
where coalesce(item_type, 'product') = #{itemType}
  and coalesce(item_id, product_id) = #{itemId}
  and shop_dept_id = #{locationDeptId}
  and warehouse_id = #{locationDeptId}

select from inv_stock where stock_id in
#{stockId}
order by stock_id for update

mapper.update:
update inv_stock
set locked_quantity = coalesce(locked_quantity, 0) + #{quantity},
    available_quantity = coalesce(available_quantity, 0) - #{quantity},
    version = version + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and version = #{version}
  and #{quantity} > 0
  and coalesce(available_quantity, 0) >= #{quantity}

update inv_stock
set locked_quantity = coalesce(locked_quantity, 0) - #{quantity},
    available_quantity = coalesce(available_quantity, 0) + #{quantity},
    version = version + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and version = #{version}
  and #{quantity} > 0
  and coalesce(locked_quantity, 0) >= #{quantity}

update inv_stock
set current_quantity = coalesce(current_quantity, 0) - #{quantity},
    locked_quantity = coalesce(locked_quantity, 0) - #{quantity},
    total_cost = coalesce(total_cost, 0) - #{deductCost},
    last_out_time = sysdate(),
    version = version + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and version = #{version}
  and #{quantity} > 0
  and coalesce(current_quantity, 0) >= #{quantity}
  and coalesce(locked_quantity, 0) >= #{quantity}
  and coalesce(total_cost, 0) >= #{deductCost}

